import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, ' as orbitParams } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Atlas region dimensions
  const REGION_WIDTH = 512;
  const REGION_HEIGHT = 320;
  const ASPECT = REGION_WIDTH / REGION_HEIGHT;

  // Plane geometry matching the atlas region aspect ratio
  const geometry = new PlaneGeometry(ASPECT, 1);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously; material will be updated when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // No primitives to apply for this node (empty list)
  // Ensure userData structure exists for consistency
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose texture if it was set
    if (material.map && material.map.dispose) {
      material.map.dispose();
    }

    // No GSAP timelines were created for this node, but guard in case
    if (root.userData._gsapTimeline) {
      root.userData._gsapTimeline.kill();
    }
  };

  return root;
}
